    let zero = vDomain.min < 0.0 && vDomain.max > 0.0 ? 0.0 : vDomain.min
    let zeroX = scaleLinear(vDomain, plot.x, plot.x + plot.w, zero)
    for i in 0..<n {
      let raw = values[i]
      let v = isFiniteNumber(raw) ? raw : zero
      let vx = scaleLinear(vDomain, plot.x, plot.x + plot.w, v)
      let left = vx < zeroX ? vx : zeroX
      out.append(PyreonChartRect(x: left, y: plot.y + band * Double(i) + (band - bh) / 2.0, w: abs(vx - zeroX), h: bh))
    }
    return out
  }

public func hitBar(_ bars: [PyreonChartRect], _ px: Double, _ py: Double) -> Int {
    for i in 0..<bars.count {
      let b = bars[i]
      if px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h {
        return i
      }
    }
    return -1
  }

public func hitNearestX(_ points: [PyreonChartPt], _ px: Double) -> Int {
    if points.count == 0 {
      return -1
    }
    var best = 0
    var bestD = abs(points[0].x - px)
    for i in 1..<points.count {
      let d = abs(points[i].x - px)
      if d < bestD {
        bestD = d
        best = i
      }
    }
    return best
  }

public func layoutStackedBars(_ seriesValues: [[Double]], _ plot: PyreonChartRect, _ yDomain: Domain, _ gapRatio: Double) -> [StackSegment] {
    var out: [StackSegment] = []
    if seriesValues.count == 0 {
      return out
    }
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.w / Double(n)
    let bw = band * (1.0 - ratio)
    for i in 0..<n {
      var acc = 0.0
      for s in 0..<seriesValues.count {
        let v = (seriesValues[s][i] ?? 0.0)
        if !(v > 0.0) {
          continue
        }
        let yTop = scaleLinear(yDomain, plot.y + plot.h, plot.y, acc + v)
        let yBot = scaleLinear(yDomain, plot.y + plot.h, plot.y, acc)
        out.append(StackSegment(rect: PyreonChartRect(x: plot.x + band * Double(i) + (band - bw) / 2.0, y: yTop, w: bw, h: Double(abs(yBot - yTop))), seriesIndex: s, datumIndex: i, value: v))
        acc = acc + v
      }
    }
    return out
  }

public func layoutStackedBarsH(_ seriesValues: [[Double]], _ plot: PyreonChartRect, _ vDomain: Domain, _ gapRatio: Double) -> [StackSegment] {
