public func treemapTip(_ cells: [TreemapCell], _ px: Double, _ py: Double) -> [String] {
    let i = hitTreemapIndex(cells, px, py)
    if i < 0 {
      return []
    }
    let c = cells[i]
    return [c.name, plain(c.value)]
  }

public func sunburstTip(_ arcs: [SunburstArc], _ center: PyreonChartPt, _ px: Double, _ py: Double) -> [String] {
    let i = hitSunburstIndex(arcs, center, px, py)
    if i < 0 {
      return []
    }
    let a = arcs[i]
    return [a.name, plain(a.value)]
  }

public func treeTip(_ layout: TreeLayout, _ px: Double, _ py: Double, _ symbolSize: Double? = nil) -> [String] {
    let i = hitTreeIndex(layout, px, py, symbolSize)
    if i < 0 {
      return []
    }
    let n = layout.nodes[i]
    if n.value == nil {
      return [n.name]
    }
    return [n.name, plain((n.value ?? 0.0))]
  }

public func riverTip(_ layout: RiverLayout, _ px: Double, _ py: Double, _ curve: String? = nil) -> [String] {
    let i = hitRiverIndex(layout, px, py, curve)
    return i < 0 ? [] : [layout.layers[i].name]
  }

public func sankeyTip(_ layout: SankeyLayout, _ px: Double, _ py: Double) -> [String] {
    let hit = hitSankeyIndex(layout, px, py)
    if hit.node >= 0 {
      let n = layout.nodes[hit.node]
      return [n.name, plain(n.value)]
    }
    if hit.link < 0 {
      return []
    }
    let l = layout.links[hit.link]
    let from = layout.nodes[l.source]
    let to = layout.nodes[l.target]
    let fromName = from == nil ? "\(l.source)" : from.name
    let toName = to == nil ? "\(l.target)" : to.name
    return ["\(fromName) → \(toName)", plain(l.value)]
  }

public func graphTip(_ layout: GraphLayout, _ px: Double, _ py: Double) -> [String] {
    let i = hitGraphIndex(layout, px, py)
    if i < 0 {
      return []
    }
    let n = layout.nodes[i]
    if n.value == nil {
      return [n.name]
    }
    return [n.name, plain((n.value ?? 0.0))]
  }

public func ganttTip(_ layout: GanttLayout, _ px: Double, _ py: Double) -> [String] {
    let i = hitGanttIndex(layout, px, py)
    if i < 0 {
      return []
    }
    let r = layout.rows[i]
    return [r.task.name, "\(plain(ganttDurationDays(r))) days"]
  }

public func polarTip(_ layout: PolarLayout, _ series: [PolarSeries], _ px: Double, _ py: Double) -> [String] {
    let hit = hitPolarIndex(layout, px, py)
    if hit.sector >= 0 {
      let sec = layout.sectors[hit.sector]
      let s = series[sec.series]
      let name = s == nil ? "Series \(sec.series + 1)" : s.name
      return [name, plain(sec.value)]
    }
    if hit.line < 0 {
      return []
    }
    let line = layout.lines[hit.line]
    let s = series[line.series]
    let name = s == nil ? "Series \(line.series + 1)" : s.name
    return [name]
  }

public func calendarTip(_ layout: CalendarLayout, _ values: [CalendarValue], _ px: Double, _ py: Double) -> [String] {
    let i = hitCalendarIndex(layout, px, py)
    if i < 0 {
      return []
    }
    let date = layout.cells[i].date
    for v in values {
      if v.date == date {
        return [date, plain(v.value)]
      }
    }
    return [date]
  }

public func geoTip(_ layout: GeoLayout, _ values: [GeoValue], _ px: Double, _ py: Double) -> [String] {
    let i = hitGeoIndex(layout, px, py)
    if i < 0 {
      return []
    }
    let name = layout.regions[i].name
    let v = geoValueOf(values, name)
    return v == v ? [name, plain(v)] : [name]
  }

public func funnelTip(_ stages: [FunnelStage], _ plot: PyreonChartRect, _ px: Double, _ py: Double, _ options: FunnelOptions? = nil) -> [String] {
    let i = hitFunnel(stages, plot, px, py, options)
    if i < 0 {
      return []
    }
    let s = stages[i]
    return [s.label, plain(s.value)]
  }

public func pieTip(_ slices: [Slice], _ box: PyreonChartRect, _ innerRatio: Double, _ px: Double, _ py: Double) -> [String] {
    let fit = fitCircle(box)
    let i = hitArc(layoutArcs(slices), fit.center, fit.radius, fit.radius * innerRatio, PyreonChartPt(x: px, y: py))
    if i < 0 {
      return []
    }
    let s = slices[i]
    var total = 0.0
    for x in slices {
      total += x.value
    }
    let pct = total > 0.0 ? floor(Double((s.value / total) * 100.0 + 0.5)) : 0.0
    return [s.label, "\(plain(s.value)) (\(plain(pct))%)"]
  }

public func renderTooltip(_ lines: [String], _ at: PyreonChartPt, _ bounds: PyreonChartRect, _ opts: TooltipOptions, _ measure: (String, Double) -> Double) -> [PyreonDrawCmd] {
    var cmds: [PyreonDrawCmd] = []
    if lines.count == 0 {
      return cmds
    }
    let lineH = opts.fontSize * 1.4
    var w = 0.0
    for l in lines {
      let m = measure(l, opts.fontSize)
      if m > w {
        w = m
      }
    }
    let size = Size(w: w + opts.pad * 2.0, h: lineH * Double(lines.count) + opts.pad * 2.0 - (lineH - opts.fontSize))
    let p = placeTooltip(at, size, bounds, 12.0)
    let r = opts.radius
    cmds.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: p.x, y: p.y, w: size.w, h: size.h), fill: opts.fill, corners: [r, r, r, r]))
    cmds.append(PyreonDrawCmd(kind: "polyline", stroke: opts.border, width: 1.0, points: [PyreonChartPt(x: p.x, y: p.y), PyreonChartPt(x: p.x + size.w, y: p.y), PyreonChartPt(x: p.x + size.w, y: p.y + size.h), PyreonChartPt(x: p.x, y: p.y + size.h), PyreonChartPt(x: p.x, y: p.y)]))
    var y = p.y + opts.pad
    for l in lines {
      cmds.append(PyreonDrawCmd(kind: "text", fill: opts.text, text: l, at: PyreonChartPt(x: p.x + opts.pad, y: y), size: opts.fontSize, align: "start", baseline: "top"))
      y = y + lineH
    }
    return cmds
  }

public func bubbleRadii(_ raw: [Double], _ minR: Double, _ maxR: Double) -> [Double] {
    var clean: [Double] = []
    var hi = 0.0
    for v in raw {
      let c = isFiniteNumber(v) && v > 0.0 ? v : 0.0
      clean.append(c)
      if c > hi {
        hi = c
      }
    }
    var out: [Double] = []
    for c in clean {
      out.append(hi == 0.0 ? minR : minR + sqrt(Double(Double(c) / hi)) * (maxR - minR))
    }
    return out
  }

public func clampWindow(_ win: ZoomWindow) -> ZoomWindow {
    var span = win.end - win.start
    if span < MIN_SPAN {
      span = MIN_SPAN
    }
    if span > 1.0 {
      span = 1.0
    }
    var start = win.start
    if start < 0.0 {
      start = 0.0
    }
    if start + span > 1.0 {
      start = 1.0 - span
    }
    return ZoomWindow(start: start, end: start + span)
  }

public func zoomWindow(_ win: ZoomWindow, _ factor: Double, _ centerFrac: Double) -> ZoomWindow {
    let span = win.end - win.start
    let c = win.start + span * (centerFrac < 0.0 ? 0.0 : centerFrac > 1.0 ? 1.0 : centerFrac)
    let nextSpan = span * factor
    let frac = span <= 0.0 ? 0.5 : (c - win.start) / span
    return clampWindow(ZoomWindow(start: c - nextSpan * frac, end: c + nextSpan * (1.0 - frac)))
  }

public func panWindow(_ win: ZoomWindow, _ deltaFrac: Double) -> ZoomWindow {
    let span = win.end - win.start
    return clampWindow(ZoomWindow(start: win.start + deltaFrac * span, end: win.end + deltaFrac * span))
  }

public func isFullWindow(_ win: ZoomWindow) -> Bool { win.start <= 0.0 && win.end >= 1.0 }

public func sliceRange(_ win: ZoomWindow, _ n: Int) -> SliceRange {
    if n <= 0 {
      return SliceRange(from: 0, to: 0)
    }
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    let startAt = win.start * nF
    let endAt = win.end * nF
    var from = 0
    var fromF = 0.0
    while fromF + 1.0 <= startAt && from < n - 1 {
      from = from + 1
      fromF = fromF + 1.0
    }
    var to = 0
    var toF = 0.0
    while toF < endAt && to < n {
      to = to + 1
      toF = toF + 1.0
    }
    if to < from + 1 {
      to = from + 1
    }
    return SliceRange(from: from, to: to)
  }

public func presetWindow(_ count: Int, _ total: Int) -> ZoomWindow {
    if count <= 0 || total <= 0 || count >= total {
      return ZoomWindow(start: 0.0, end: 1.0)
    }
    var c = 0.0
    for i in 0..<count {
      c = c + 1.0
    }
    var t = 0.0
    for i in 0..<total {
      t = t + 1.0
    }
    return ZoomWindow(start: 1.0 - c / t, end: 1.0)
  }

public func presetIsActive(_ preset: ZoomPreset, _ total: Int, _ win: ZoomWindow) -> Bool {
    let target = presetWindow(preset.count, total)
    let ds = win.start - target.start
    let de = win.end - target.end
    let ads = ds < 0.0 ? 0.0 - ds : ds
    let ade = de < 0.0 ? 0.0 - de : de
    return ads < 0.000001 && ade < 0.000001
  }

public func renderPresets(_ items: [ZoomPreset], _ total: Int, _ win: ZoomWindow, _ canvas: PyreonChartRect, _ opts: PresetOptions, _ measure: (String, Double) -> Double) -> PresetLayout {
    var cmds: [PyreonDrawCmd] = []
    var boxes: [PyreonChartRect] = []
    if items.count == 0 {
      return PresetLayout(cmds: cmds, boxes: boxes, height: 0.0)
    }
    var widths: [Double] = []
    var span = 0.0
    for i in 0..<items.count {
      let it = items[i]
      let tw = measure(it.label, opts.fontSize) + opts.padX * 2.0
      widths.append(tw)
      span = span + tw
      if i > 0 {
        span = span + opts.gap
      }
    }
    var x = canvas.x + canvas.w - opts.inset - span
    let y = canvas.y + canvas.h - PRESET_STRIP_HEIGHT + opts.padY
    let h = PRESET_STRIP_HEIGHT - opts.padY * 2.0
    for i in 0..<items.count {
      let it = items[i]
      let tw = widths[i]
      let b = PyreonChartRect(x: x, y: y, w: tw, h: h)
      boxes.append(b)
      let active = presetIsActive(it, total, win)
      cmds.append(PyreonDrawCmd(kind: "rect", rect: b, fill: active ? opts.activeFill : opts.idleFill))
      cmds.append(PyreonDrawCmd(kind: "text", fill: active ? opts.activeText : opts.idleText, text: it.label, at: PyreonChartPt(x: b.x + Double(b.w) / 2.0, y: b.y + Double(b.h) / 2.0), size: opts.fontSize, align: "middle", baseline: "middle"))
      x = x + tw + opts.gap
    }
    return PresetLayout(cmds: cmds, boxes: boxes, height: PRESET_STRIP_HEIGHT)
  }

public func presetHit(_ boxes: [PyreonChartRect], _ x: Double, _ y: Double) -> Int {
    for i in 0..<boxes.count {
      let b = boxes[i]
      if x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h {
        return i
      }
    }
    return -1
  }

public func isHiddenSeries(_ hidden: [Int], _ i: Int) -> Bool {
    for k in 0..<hidden.count {
      if hidden[k] == i {
        return true
      }
    }
    return false
  }

public func legendToggle(_ hidden: [Int], _ i: Int) -> [Int] {
    var out: [Int] = []
    var found = false
    for k in 0..<hidden.count {
      let h = hidden[k]
      if h == i {
        found = true
      } else {
        out.append(h)
      }
    }
    if !found {
      out.append(i)
    }
    return out
  }

public func hideHiddenSeries(_ series: [Series], _ hidden: [Int]) -> [Series] {
    if hidden.count == 0 {
      return series
    }
    var out: [Series] = []
    for i in 0..<series.count {
      let s = series[i]
      if isHiddenSeries(hidden, i) {
        var zeroed: [Double] = []
        if s.kind == "stacked" || s.kind == "grouped" {
          for k in 0..<s.values.count {
            zeroed.append(0.0)
          }
        }
        out.append(Series(kind: s.kind, values: zeroed, color: s.color, width: s.width, radius: s.radius, label: s.label, curve: s.curve, showValues: false, axis: s.axis, effect: s.effect, symbol: s.symbol, symbolRepeat: s.symbolRepeat))
      } else {
        out.append(s)
      }
    }
    return out
  }

public func legendHitIndex(_ boxes: [PyreonChartRect], _ x: Double, _ y: Double) -> Int {
    for i in 0..<boxes.count {
      let b = boxes[i]
      if x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h {
        return i
      }
    }
    return -1
  }

public func pagerHit(_ pager: LegendPager, _ x: Double, _ y: Double) -> Double {
    let p = pager.prev
    if pager.hasPrev && x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h {
      return -1.0
    }
    let n = pager.next
    if pager.hasNext && x >= n.x && x <= n.x + n.w && y >= n.y && y <= n.y + n.h {
      return 1.0
    }
    return 0.0
  }

public func renderNavigator(_ values: [Double], _ color: String, _ win: ZoomWindow, _ canvas: PyreonChartRect, _ gridFill: String) -> NavigatorLayout {
    let stripW = canvas.w - NAV_INSET * 2.0
    let strip = PyreonChartRect(x: canvas.x + NAV_INSET, y: canvas.y + canvas.h - NAV_STRIP_HEIGHT + NAV_PAD_Y, w: stripW < 0.0 ? 0.0 : stripW, h: NAV_STRIP_HEIGHT - NAV_PAD_Y * 2.0)
    var cmds: [PyreonDrawCmd] = []
    cmds.append(PyreonDrawCmd(kind: "rect", rect: strip, fill: gridFill))
    if values.count > 1 {
      var lo = 0.0
      var hi = 0.0
      var seen = false
      for i in 0..<values.count {
        let v = values[i]
        if isFiniteNumber(v) {
          if !seen {
            lo = v
            hi = v
            seen = true
          } else {
            if v < lo {
              lo = v
            }
            if v > hi {
              hi = v
            }
          }
        }
      }
      if seen {
        var safe: [Double] = []
        for i in 0..<values.count {
          let v = values[i]
          safe.append(!isFiniteNumber(v) ? lo : v)
        }
        let pts = layoutSeriesPoints(safe, strip, Domain(min: lo < 0.0 ? lo : 0.0, max: hi <= lo ? lo + 1.0 : hi))
        let last = pts[pts.count - 1]
        let first = pts[0]
        var poly: [PyreonChartPt] = []
        for i in 0..<pts.count {
          poly.append(pts[i])
        }
        poly.append(PyreonChartPt(x: last.x, y: strip.y + strip.h))
        poly.append(PyreonChartPt(x: first.x, y: strip.y + strip.h))
        cmds.append(PyreonDrawCmd(kind: "polygon", fill: withAlpha(color, 0.35), points: poly))
      }
    }
    let bx0 = strip.x + strip.w * win.start
    let bx1 = strip.x + strip.w * win.end
    cmds.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: bx0, y: strip.y, w: bx1 - bx0, h: strip.h), fill: "rgba(37,99,235,0.18)"))
    cmds.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: bx0 - 3.0, y: strip.y, w: 6.0, h: strip.h), fill: "#2563eb"))
    cmds.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: bx1 - 3.0, y: strip.y, w: 6.0, h: strip.h), fill: "#2563eb"))
    return NavigatorLayout(cmds: cmds, strip: strip, height: NAV_STRIP_HEIGHT)
  }

public func navigatorHit(_ strip: PyreonChartRect, _ win: ZoomWindow, _ x: Double) -> Int {
    let bx0 = strip.x + strip.w * win.start
    let bx1 = strip.x + strip.w * win.end
    let dl = x - bx0
    let dr = x - bx1
    if (dl < 0.0 ? 0.0 - dl : dl) <= HANDLE_GRAB {
      return 2
    }
    if (dr < 0.0 ? 0.0 - dr : dr) <= HANDLE_GRAB {
      return 3
    }
    return 1
  }

public func navigatorDrag(_ kind: Int, _ startWin: ZoomWindow, _ deltaFrac: Double) -> ZoomWindow {
    if kind == 2 {
      let s = startWin.start + deltaFrac
      let cap = startWin.end - NAV_MIN_SPAN
      return clampWindow(ZoomWindow(start: s < cap ? s : cap, end: startWin.end))
    }
    if kind == 3 {
      let e = startWin.end + deltaFrac
      let floor = startWin.start + NAV_MIN_SPAN
      return clampWindow(ZoomWindow(start: startWin.start, end: e > floor ? e : floor))
    }
    return clampWindow(ZoomWindow(start: startWin.start + deltaFrac, end: startWin.end + deltaFrac))
  }

public func brushRange(_ plotX: Double, _ plotW: Double, _ x1: Double, _ x2: Double, _ win: ZoomWindow, _ n: Int) -> BrushRange {
    let lo = x1 < x2 ? x1 : x2
    let hi = x1 < x2 ? x2 : x1
    let span = win.end - win.start
    let rawLo = plotW <= 0.0 ? 0.0 : (lo - plotX) / plotW
    let rawHi = plotW <= 0.0 ? 0.0 : (hi - plotX) / plotW
    let cLo = rawLo < 0.0 ? 0.0 : rawLo > 1.0 ? 1.0 : rawLo
    let cHi = rawHi < 0.0 ? 0.0 : rawHi > 1.0 ? 1.0 : rawHi
    let r = sliceRange(ZoomWindow(start: win.start + cLo * span, end: win.start + cHi * span), n)
    return BrushRange(start: r.from, end: r.to - 1)
  }

public func countToDouble(_ k: Int) -> Double {
    var f = 0.0
    if k >= 0 {
      for i in 0..<k {
        f = f + 1.0
      }
    } else {
      for i in 0..<0 - k {
        f = f - 1.0
      }
    }
    return f
  }

public func brushBand(_ plot: PyreonChartRect, _ sel: BrushRange, _ win: ZoomWindow, _ n: Int) -> BrushBand {
    let r = sliceRange(win, n)
    let nView = r.to - r.from
    if nView <= 0 {
      return BrushBand(visible: false, lo: 0.0, hi: 0.0)
    }
    let bw = plot.w / countToDouble(nView)
    var lo = plot.x + countToDouble(sel.start - r.from) * bw
    var hi = plot.x + countToDouble(sel.end - r.from + 1) * bw
    if hi < plot.x || lo > plot.x + plot.w {
      return BrushBand(visible: false, lo: 0.0, hi: 0.0)
    }
    if lo < plot.x {
      lo = plot.x
    }
    if hi > plot.x + plot.w {
      hi = plot.x + plot.w
    }
    return BrushBand(visible: true, lo: lo, hi: hi)
  }

public func renderBrushBand(_ plot: PyreonChartRect, _ lo: Double, _ hi: Double, _ edge: String) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: lo, y: plot.y, w: hi - lo, h: plot.h), fill: "rgba(99,102,241,0.15)"))
    out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: lo, y: plot.y), to: PyreonChartPt(x: lo, y: plot.y + plot.h), stroke: edge, width: 1.0, dash: [3.0, 3.0]))
    out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: hi, y: plot.y), to: PyreonChartPt(x: hi, y: plot.y + plot.h), stroke: edge, width: 1.0, dash: [3.0, 3.0]))
    return out
  }

public func describeChart(_ input: A11yInput) -> String {
    let fmt = (input.format ?? plain)
    var parts: [String] = []
    let title = (input.title ?? "Chart")
    if input.series.count == 0 {
      return "\(title): no data."
    }
    parts.append("\(title).")
    let n = input.series.count
    parts.append(n == 1 ? "1 series" : "\(n) series")
    if input.categories.count > 0 {
      parts.append("over \(input.categories.count) categories from \(input.categories[0]) to \(input.categories[input.categories.count - 1]).")
    } else {
      parts.append(".")
    }
    for s in input.series {
      if s.values.count == 0 {
        parts.append("\(s.label): empty.")
        continue
      }
      var lo = 0.0
      var hi = 0.0
      var loAt = 0
      var hiAt = 0
      var first = 0.0
      var last = 0.0
      var seen = 0
      for i in 0..<s.values.count {
        let v = s.values[i]
        if v != v {
          continue
        }
        if seen == 0 {
          lo = v
          hi = v
          loAt = i
          hiAt = i
          first = v
        }
        if v < lo {
          lo = v
          loAt = i
        }
        if v > hi {
          hi = v
          hiAt = i
        }
        last = v
        seen = seen + 1
      }
      if seen == 0 {
        parts.append("\(s.label): empty.")
        continue
      }
      let dir = last > first ? "rising" : last < first ? "falling" : "flat"
      let at = { (i: Int) in input.categories[i] != nil ? " at \(input.categories[i])" : "" }
      let other = (s.values2 ?? [])
      if other.count > 0 {
        var olo = 0.0
        var ohi = 0.0
        var oseen = 0
        for i in 0..<other.count {
          let v = other[i]
          if v != v {
            continue
          }
          if oseen == 0 {
            olo = v
            ohi = v
          }
          if v < olo {
            olo = v
          }
          if v > ohi {
            ohi = v
          }
          oseen = oseen + 1
        }
        if oseen > 0 {
          parts.append("\(s.label), \(s.kind): upper bound \(dir) from \(fmt(first)) to \(fmt(last)), " + "ranging \(fmt(lo))\(at(loAt)) to \(fmt(hi))\(at(hiAt)); " + "lower bound ranging \(fmt(olo)) to \(fmt(ohi)).")
          continue
        }
      }
      parts.append("\(s.label), \(s.kind): \(dir) from \(fmt(first)) to \(fmt(last)), " + "ranging \(fmt(lo))\(at(loAt)) to \(fmt(hi))\(at(hiAt)).")
    }
    return { (s: String, f: String, r: String) -> String in s.replacingOccurrences(of: f, with: r, options: [], range: s.range(of: f)) }(parts.joined(separator: " "), " .", ".")
  }

public func withError(_ fmt: (Double) -> String, _ v: Double, _ s: A11ySeries, _ i: Int) -> String {
    let lo = (s.errLow ?? [])
    let hi = (s.errHigh ?? [])
    if i >= lo.count || i >= hi.count {
      return fmt(v)
    }
    let l = lo[i]
    let h = hi[i]
    if !isFiniteNumber(l) || !isFiniteNumber(h) {
      return fmt(v)
    }
    return "\(fmt(v)) (\(fmt(l)) to \(fmt(h)))"
  }

public func chartTable(_ input: A11yInput) -> A11yTable {
    let fmt = (input.format ?? plain)
    var headers = ["Category"]
    for s in input.series {
      let other = (s.values2 ?? [])
      let rs = (s.rValues ?? [])
      if other.count > 0 {
        headers.append("\(s.label) (upper)")
        headers.append("\(s.label) (lower)")
      } else {
        headers.append(s.label)
      }
      if rs.count > 0 {
        headers.append("\(s.label) (size)")
      }
    }
    var n = input.categories.count
    for s in input.series {
      if s.values.count > n {
        n = s.values.count
      }
    }
    var rows: [[String]] = []
    for i in 0..<n {
      var row = [i < input.categories.count ? input.categories[i] : "\(i + 1)"]
      for s in input.series {
        let other = (s.values2 ?? [])
        let rs = (s.rValues ?? [])
        let two = other.count > 0
        let sized = rs.count > 0
        if i >= s.values.count {
          row.append("")
          if two {
            row.append("")
          }
          if sized {
            row.append("")
          }
          continue
        }
        let v = s.values[i]
        row.append(isFiniteNumber(v) ? withError(fmt, v, s, i) : "")
        if two {
          if i >= other.count {
            row.append("")
          } else {
            let v2 = other[i]
            row.append(isFiniteNumber(v2) ? fmt(v2) : "")
          }
        }
        if sized {
          if i >= rs.count {
            row.append("")
          } else {
            let r = rs[i]
            row.append(isFiniteNumber(r) ? fmt(r) : "")
          }
        }
      }
      rows.append(row)
    }
    return A11yTable(headers: headers, rows: rows)
  }

public func finite(_ v: Double) -> Bool { v == v }

public func smaValues(_ values: [Double], _ window: Int) -> [Double] {
    let n = values.count
    var out: [Double] = []
    let w = window < 1 ? 1 : window
    var sum = 0.0
    for i in 0..<n {
      let v = values[i]
      sum = sum + (finite(v) ? v : 0.0)
      if i >= w {
        let gone = values[i - w]
        sum = sum - (finite(gone) ? gone : 0.0)
      }
      out.append(i >= w - 1 ? sum / Double(w) : GAP)
    }
    return out
  }

public func emaValues(_ values: [Double], _ window: Int) -> [Double] {
    let n = values.count
    var out: [Double] = []
    let w = window < 1 ? 1 : window
    let alpha = 2.0 / (Double(w) + 1.0)
    var prev = GAP
    var seed = 0.0
    for i in 0..<n {
      let v = values[i]
      let vv = finite(v) ? v : 0.0
      if i < w - 1 {
        seed = seed + vv
        out.append(GAP)
      } else {
        if i == w - 1 {
          prev = (seed + vv) / Double(w)
          out.append(prev)
        } else {
          prev = vv * alpha + prev * (1.0 - alpha)
          out.append(prev)
        }
      }
    }
    return out
  }

public func stdevValues(_ values: [Double], _ window: Int) -> [Double] {
    let n = values.count
    var out: [Double] = []
    let w = window < 1 ? 1 : window
    for i in 0..<n {
      if i < w - 1 {
        out.append(GAP)
        continue
      }
      var mean = 0.0
      for k in i - w + 1...i {
        mean = mean + values[k]
      }
      mean = Double(mean) / Double(w)
      var acc = 0.0
      for k in i - w + 1...i {
        let d = values[k] - mean
        acc = acc + d * d
      }
      out.append(sqrt(Double(Double(acc) / Double(w))))
    }
    return out
  }

public func trendValues(_ values: [Double]) -> [Double] {
    let n = values.count
    var out: [Double] = []
    if n == 0 {
      return out
    }
    var sx = 0.0
    var sy = 0.0
    var sxx = 0.0
    var sxy = 0.0
    var m = 0.0
    for i in 0..<n {
      let v = values[i]
      if !finite(v) {
        continue
      }
      let x = Double(i) * 1.0
      sx = sx + x
      sy = sy + v
      sxx = sxx + x * x
      sxy = sxy + x * v
      m = m + 1.0
    }
    let denom = m * sxx - sx * sx
    let slope = m < 2.0 || denom == 0.0 ? 0.0 : (m * sxy - sx * sy) / denom
    let intercept = m == 0.0 ? 0.0 : (sy - slope * sx) / m
    for i in 0..<n {
      out.append(intercept + slope * Double(i))
    }
    return out
  }

public func bollingerEdge(_ values: [Double], _ window: Int, _ k: Double, _ sign: Double) -> [Double] {
    let mid = smaValues(values, window)
    let sd = stdevValues(values, window)
    var out: [Double] = []
    for i in 0..<values.count {
      let m = mid[i]
      let s = sd[i]
      out.append(finite(m) && finite(s) ? m + sign * k * s : GAP)
    }
    return out
  }

public func binValues(_ values: [Double], _ count: Double) -> [Bin] {
    var finite: [Double] = []
    for v in values {
      if isFiniteNumber(v) {
        finite.append(v)
      }
    }
    var out: [Bin] = []
    if finite.count == 0 {
      return out
    }
    var lo = finite[0]
    var hi = finite[0]
    for v in finite {
      if v < lo {
        lo = v
      }
      if v > hi {
        hi = v
      }
    }
    let target = count < 1.0 ? 1.0 : count
    if hi == lo {
      out.append(Bin(x0: lo, x1: lo + 1.0, count: Double(finite.count)))
      return out
    }
    let dom = niceDomain(Domain(min: lo, max: hi), target)
    let step = niceStep((hi - lo) / target)
    let limit = 500
    var x0 = dom.min
    var k = 0
    while x0 < dom.max - step * 0.000001 && k < limit {
      out.append(Bin(x0: x0, x1: x0 + step, count: 0.0))
      x0 = x0 + step
      k = k + 1
    }
    if out.count == 0 {
      out.append(Bin(x0: dom.min, x1: dom.max, count: 0.0))
    }
    let last = out.count - 1
    for v in finite {
      var idx = 0
      var edge = dom.min + step
      while edge <= v && idx < last {
        idx = idx + 1
        edge = edge + step
      }
      out[idx].count = out[idx].count + 1.0
    }
    return out
  }

public func binLabel(_ b: Bin) -> String { "\(plain(b.x0))–\(plain(b.x1))" }
